contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: take an amount to deposit
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read before values via public getters
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        // perform Deposit by sending ETH to c (use receive entrypoint)
        // call Deposit explicitly to match behavior
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // read after values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterEth = address(c).balance;

        // general invariant: recorded balance increased by amount and contract ETH increased by amount
        assert(afterRecorded == beforeRecorded + amount && afterEth == beforeEth + amount);
    }

    // allow this test contract to receive ETH so it can forward it to c
    receive() external payable {}
}

